    ]
  }
}

rules.bad_example:
{
  "version": 1,
  "hooks": { "afterFileEdit": [{ "command": "./hooks/format.sh" }] }
}
(.cursor/hooks.json in a project; the script is .cursor/hooks/format.sh)

{
  "name": "example-plugin",
  "rules": "../shared/rules/"
}
(mcp.json uses ${API_TOKEN}, which variables does not declare)

rules.good_example:
{
  "name": "read-file",
  "title": "Read File",
  "description": "Reads a file from disk and returns its contents",
  "inputSchema": {
    "type": "object",
    "properties": {
      "path": { "type": "string" }
    },
    "required": ["path"]
  },
  "outputSchema": {
    "type": "object"
  },
  "icons": [{"src": "https://example.com/icon.png"}]
}

{
  "name": "search",
  "description": "Searches for files matching a query string",
  "inputSchema": {
    "type": "object",
    "properties": {
      "query": { "type": "string" }
    }
  },
  "outputSchema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "type": "object"
  }
}

rules.bad_example:
{
  "name": "search",
  "description": "Searches for files matching a query string",
  "inputSchema": {
    "type": "invalid_type"
  },
  "outputSchema": {
    "type": 42
  }
}

rules.good_example:
{
  "name": "deploy",
  "description": "Deploys the application to the specified environment with rollback support",
  "inputSchema": { "type": "object" }
}

